mapper.select:
WITH RECURSIVE comment_tree AS ( -- ① 최상위(부모) 댓글 조회 SELECT C.CMNT_SN, C.POST_SN, C.CMNT_CN, C.CMNT_WRTR_SN, C.CMNT_FRST_WRT_DT, C.CMNT_LAST_MDFCN_DT, C.DEL_YN, C.PARENT_CMNT_SN FROM TB_COMMENT C WHERE C.POST_SN = #{postSn} AND C.PARENT_CMNT_SN IS NULL AND C.DEL_YN = FALSE
UNION ALL
-- ② 자식(대댓글) 재귀적으로 조회 SELECT c.CMNT_SN, c.POST_SN, c.CMNT_CN, c.CMNT_WRTR_SN, c.CMNT_FRST_WRT_DT, c.CMNT_LAST_MDFCN_DT, c.DEL_YN, c.PARENT_CMNT_SN FROM TB_COMMENT c INNER JOIN comment_tree ct ON c.PARENT_CMNT_SN = ct.CMNT_SN WHERE c.DEL_YN = FALSE ) SELECT CMNT_SN, POST_SN, CMNT_CN, CMNT_WRTR_SN, CMNT_FRST_WRT_DT, CMNT_LAST_MDFCN_DT, DEL_YN, PARENT_CMNT_SN FROM comment_tree ORDER BY CASE WHEN PARENT_CMNT_SN IS NULL THEN CMNT_SN ELSE PARENT_CMNT_SN END ASC, CMNT_SN ASC;

mapper.update:
UPDATE TB_COMMENT
SET
    CMNT_CN = #{dto.cmntCn},
    CMNT_LAST_MDFCN_DT = #{dto.cmntLastMdfcnDt}
WHERE CMNT_SN = #{dto.cmntSn}
  AND DEL_YN = FALSE
